from collections import defaultdict
def runs(seps, n):
    out=[]; s=0
    for x in sorted(set(seps))+[n]:
        if x>s: out.append((s,x))
        s=x+1
    return out

def transform(grid):
    H,W=len(grid),len(grid[0])
    sepc=[c for c in range(W) if len({r[c] for r in grid})==1 and grid[0][c]!=0]
    sepr=[r for r in range(H) if len(set(grid[r]))==1 and grid[r][0]!=0]
    lc=grid[0][sepc[0]] if sepc else grid[sepr[0]][0]
    rowb=runs(sepr,H); colb=runs(sepc,W)
    out=[row[:] for row in grid]
    where=defaultdict(list)
    for bi,(a,b) in enumerate(rowb):
        for bj,(c,d) in enumerate(colb):
            for i in range(a,b):
                for j in range(c,d):
                    v=grid[i][j]
                    if v not in (0,lc): where[v].append((bi,bj))
    for col,blks in where.items():
        blks=set(blks)
        ris=sorted({r for r,_ in blks}); cis=sorted({c for _,c in blks})
        if len(ris)==2 and len(cis)==2 and len(blks)==3:
            miss=[(r,c) for r in ris for c in cis if (r,c) not in blks][0]
            a,b=rowb[miss[0]]; c,d=colb[miss[1]]; bh,wid=b-a,d-c
            if (miss[0]-1,miss[1]) in blks:   # copy from above, vflip
                src=rowb[miss[0]-1]; cells=[(i-src[0],j-c) for i in range(*src) for j in range(c,d) if grid[i][j]==col]
                tgt={(bh-1-r,cc) for r,cc in cells}
            elif (miss[0]+1,miss[1]) in blks:
                src=rowb[miss[0]+1]; cells=[(i-src[0],j-c) for i in range(*src) for j in range(c,d) if grid[i][j]==col]
                tgt={(bh-1-r,cc) for r,cc in cells}
            elif (miss[0],miss[1]-1) in blks: # from left, hmirror
                src=colb[miss[1]-1]; cells=[(i-a,j-src[0]) for i in range(a,b) for j in range(*src) if grid[i][j]==col]
                tgt={(r,wid-1-cc) for r,cc in cells}
            else:
                src=colb[miss[1]+1]; cells=[(i-a,j-src[0]) for i in range(a,b) for j in range(*src) if grid[i][j]==col]
                tgt={(r,wid-1-cc) for r,cc in cells}
            for r,cc in tgt: out[a+r][c+cc]=col
    return out

